insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('3b595f11-670f-4dbd-837f-c9d1963d9938', 'f83eae2c-c6a7-4d35-af31-bedf36f10aa7', '2026-06-01', '55', NULL, '["3","3","2","3","2","3","2","2","3","2","3","3","3","4","3","3","2","3","2","3","3","2","3","3","3","2"]'::jsonb, 'Technical Troubleshooting', 'Task Coordination', 'Technical Skills & Reliability', 'Maintenance Performance', 'Overall Team Contribution', NULL, NULL, NULL, '2026-09-20T14:43:16.641684+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('1b007db1-9e7d-4e9f-8864-53892ab67fdc', 'c07e5848-9a2f-4595-86d2-c7736173367f', '2026-06-02', '50', NULL, '["3","3","4","3","3","3","2","3","3","2","2","3","3","2","2","2","2","2","2","2","3","3","2","2","2","2"]'::jsonb, 'Significant improvement is required in leadership effectiveness, initiative, HR process compliance, quality of work, communication accuracy, and HR system proficiency. Greater accountability, ownership, and proactive management of HR activities are needed to meet the expectations of the HR Manager role.', 'Focus on improving leadership and people management skills, strengthening knowledge and use of HR systems, enhancing the quality and timeliness of HR deliverables, and taking greater initiative in resolving HR-related issues. Develop stronger planning, delegation, and decision-making capabilities to improve departmental performance.', 'Demonstrates professionalism and maintains respectful working relationships with colleagues and employees. Possesses a basic understanding of HR processes and continues to support routine HR operations. Maintains acceptable standards of conduct and contributes positively when assigned responsibilities.', 'Jackline Kirumaghio demonstrates professionalism and maintains positive working relationships within the organisation. However, performance during this evaluation period indicates a need for substantial improvement in leadership, work quality, HR process compliance, communication accuracy, and system utilization. Greater ownership, accountability, and proactive management of HR functions are required to effectively meet the expectations of the HR Manager position.', 'The overall score of 50/100 reflects performance below the expected standard for an HR Manager. While there are strengths in professional conduct and basic HR process knowledge, improvement is required in leadership, initiative, quality of deliverables, communication, compliance, and system competency. A structured Performance Improvement Plan (PIP) with clearly defined KPIs, monthly reviews, and targeted development objectives is strongly recommended.', NULL, NULL, NULL, '2026-09-20T14:43:19.406454+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('921a130f-68bb-4370-a462-a57d28dc7e13', 'e38a91d5-a0af-4246-a8c8-ea695e2827df', '2026-06-02', '48', NULL, '["3","3","3","2","3","2","2","3","2","2","2","2","3","2","3","3","3","2","2","2","2","2","2","3","2","2"]'::jsonb, 'The evaluation indicates significant development is required in leadership effectiveness, strategic planning, service provider management, communication, and cross-functional collaboration. Greater focus is needed on driving engineering initiatives, enforcing compliance standards, managing contractor performance, and improving coordination with internal departments. The low scores in leadership, communication, and strategy suggest a need for stronger managerial presence and proactive operational oversight.', 'Develop and implement a structured engineering strategy aligned with organisational objectives, strengthen service provider monitoring through clear KPIs and SLAs, and improve reporting accuracy and responsiveness to client escalations. More attention should be given to policy compliance, team engagement, delegation, and data-driven decision-making to improve overall departmental performance.', 'Demonstrates a reasonable understanding of maintenance operations, PPM planning, asset management, and reactive maintenance processes. Despite challenges in strategic and leadership areas, maintains acceptable attendance and continues to support day-to-day engineering operations. Maintenance and asset management performance was the strongest area of the evaluation.', 'Azlan Ahamed continues to support the engineering function and maintain operational activities across facilities. However, the evaluation reflects performance below the expectations of a Head of Engineering role. Improvement is required in strategic leadership, service provider management, team development, communication, and operational governance. Greater ownership of departmental objectives, improved contractor oversight, and more proactive leadership are expected during the next review period.', 'The overall score of 48/100 indicates that performance is currently below the required standard for a department head position. While operational maintenance activities are being managed at an acceptable level, there are substantial gaps in leadership, strategic direction, communication, compliance management, and stakeholder engagement. A structured improvement plan with clear performance objectives, leadership coaching, and quarterly performance reviews is strongly recommended.', NULL, NULL, NULL, '2026-09-20T14:43:15.661867+00:00');
