insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('732efb53-f49a-4757-9589-9a7b88b6aef5', '87299a1f-2db9-406e-b298-7ad9838d969c', '2026-08-26', '54', NULL, '["4","3","3","3","3","3","3","3","2","2","2","2","4","","2","3","3","3","4","3","3","2","3","3","2","3"]'::jsonb, 'Strengthened technical knowledge.', 'Improved task coordination.', 'Demonstrated reliability and commitment.', 'Handled duties responsibly.', 'Supported the FM team effectively.', NULL, NULL, NULL, '2026-09-20T14:43:14.903164+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('1a3a1781-76c4-4717-a4b7-cf0c43b21d9c', 'e38a91d5-a0af-4246-a8c8-ea695e2827df', '2026-09-02', '64', NULL, '["4","3","4","3","3","3","4","3","3","3","4","3","3","3","3","3","3","4","3","3","3","3","3","3","3","3"]'::jsonb, 'Further development is required in maintenance optimisation, vendor performance management, contract compliance monitoring, reporting quality, and utilisation of engineering systems and analytics to support strategic decision-making.', 'Focus on strengthening preventive maintenance planning, improving contractor and SLA management, enhancing engineering reporting accuracy, and utilising Odoo systems more effectively to improve operational visibility and asset performance.', 'Demonstrates strong commitment to engineering operations and maintains effective coordination with internal departments and service providers. Shows good leadership presence, professional conduct, and operational understanding while contributing positively to department objectives and facility performance.', 'Azlan Ahamed continues to maintain stable engineering operations and demonstrates commitment to departmental responsibilities. Positive contributions are evident in operational alignment, teamwork, and leadership. Continued focus on strategic maintenance planning, contractor management, reporting quality, and data-driven decision-making will further enhance departmental performance.', 'The overall score of 64/100 reflects satisfactory performance and demonstrates consistency in managing engineering operations. The employee shows competence in leadership, operational coordination, and engineering oversight. To achieve a higher performance level, emphasis should be placed on asset management, service provider governance, maintenance effectiveness, reporting standards, and strategic utilisation of engineering systems.', NULL, NULL, NULL, '2026-09-20T14:43:15.661867+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('9731afa1-c175-41db-b242-04f9daf6009f', '4ce946e5-2f29-448b-80cd-676250760351', '2026-09-02', '62', NULL, '["4","4","4","3","3","3","3","3","3","3","3","4","3","3","2","3","2","3","3","3","3","3","3","3","3","3","3","3","3"]'::jsonb, 'Improvement is still required in issue resolution, follow-up efficiency, escalation judgement, documentation accuracy, and proactive problem-solving. Stronger ownership of customer concerns and better utilisation of CRM systems will help improve service quality and customer satisfaction.', 'Focus on resolving customer issues more promptly, improving follow-up consistency, strengthening escalation decision-making, and enhancing CRM/ERP system utilisation. Developing a more proactive approach to identifying customer needs and preventing recurring service issues will further improve overall performance.', 'Demonstrates strong attendance and punctuality, maintains professional interactions with customers, and shows a positive attitude toward customer service responsibilities. Customer communication has improved, and the employee maintains acceptable standards of teamwork and compliance with company procedures.', 'Myla demonstrates reliability, professionalism, and improved customer communication. However, additional improvement is required in issue resolution, follow-up management, escalation accuracy, and documentation quality. Greater initiative, accountability, and proactive customer service are expected to further improve performance and customer satisfaction.', 'The overall score reflects performance that partially meets expectations and has improved compared to the previous quarter. While dependability, professionalism, and customer interaction skills continue to improve, further development is required in issue resolution, reporting accuracy, system utilisation, and proactive customer support. A structured development plan with measurable service KPIs and regular coaching is recommended.', NULL, NULL, NULL, '2026-09-20T14:43:20.117228+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('62136f92-b531-4d16-bbee-daeadad03f7f', '6beeb1d9-8f7b-46bd-92c2-7f6edbf45c1f', '2026-09-02', '62', NULL, '["4","3","4","3","4","3","2","4","3","3","4","3","3","2","3","4","3","3","3","4","2","2","3","3","2","3"]'::jsonb, 'Strengthens operational planning and leadership.', 'Improves team coordination and service delivery', 'Demonstrates strong leadership and accountability.', 'Manages facility operations effectively and maintains service standards.', 'Supports efficient and reliable facility operations.', NULL, NULL, NULL, '2026-09-20T14:43:24.102322+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('083df342-4474-4193-ad99-a58aecc6a89f', 'c07e5848-9a2f-4595-86d2-c7736173367f', '2026-09-02', '64', NULL, '["4","3","4","3","3","3","3","3","3","3","3","3","3","3","3","3","3","3","3","4","4","3","3","3","4","4"]'::jsonb, 'Needs to strengthen HR process management, improve consistency in policy compliance, and develop a more proactive approach to identifying and resolving operational HR issues. Greater focus is required on cross-functional collaboration and timely follow-up of HR deliverables.', 'Improve response times, enhance accuracy and quality control in HR documentation, and take greater ownership of department initiatives. Focus on reducing rework, ensuring deadlines are consistently met, and increasing engagement with department managers to support workforce planning and employee matters', 'Demonstrates professionalism, maintains positive working relationships, communicates clearly, and shows good judgement in handling workplace issues. Possesses solid foundational HR knowledge and adapts well to company systems and processes.', 'Jackline has maintained a professional attitude and contributes positively to the HR function. However, performance remains at a satisfactory level, and greater initiative, accountability, and consistency are required to meet the expectations of an HR Manager role. Focus should be placed on strengthening HR process execution, improving follow-up, and driving department improvements proactively.', 'Retain with Performance Improvement Plan and Development Objectives. The employee demonstrates potential and possesses key professional strengths; however, measurable improvement is required in HR operations management, leadership effectiveness, process compliance, and proactive decision-making. A review period of 3-6 months with clearly defined KPIs is recommended.', NULL, NULL, NULL, '2026-09-20T14:43:19.406454+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('0fd4282d-c276-4058-a527-82ff18782546', 'e25cc32c-8e57-4900-90b7-130d15ce592e', '2026-09-02', '65', NULL, '["4","4","3","3","4","4","4","3","3","3","3","3","3","3","3","3","3","3","3","3","4","3","3","3","3","3","3","3","3"]'::jsonb, 'Further development is required in customer service excellence, independent problem solving, and effective utilisation of CRM/ERP systems. While performance has improved, greater consistency is needed in customer issue resolution, follow-up management, and taking initiative in addressing customer concerns.', 'Continue building confidence in handling customer enquiries independently, improve response times, and focus on enhancing documentation accuracy and system proficiency. Developing stronger analytical skills to identify customer trends and recommending service improvements will contribute to higher performance levels', 'Demonstrates reliable attendance and punctuality, improved teamwork and collaboration, positive professional conduct, and stronger communication skills. Has shown willingness to learn and a noticeable improvement in customer support processes compared to the previous evaluation period', 'Faith Cherotich has shown measurable improvement during this evaluation period, 
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('09493fdf-5af2-4532-beec-bb102d2a24b3', 'e142ff26-dce3-43c5-926a-fc5e2a012147', '2026-09-02', '62', NULL, '["4","3","4","3","4","3","4","3","3","3","3","3","3","3","3","3","2","2","3","3","3","3","3","4","4","3"]'::jsonb, 'Further improvement is required in procurement task accuracy, work quality, initiative, problem-solving, and independent decision-making. Greater focus on reducing errors, improving efficiency, and taking ownership of assigned responsibilities will support continued development.', 'Continue strengthening procurement process knowledge, enhance attention to detail to reduce rework, improve proactive problem-solving abilities, and take greater initiative in managing procurement tasks independently. Focus on developing stronger planning and prioritization skills to improve overall productivity.', 'Demonstrates good professional conduct, accountability, and cooperation with colleagues. Shows improving knowledge of procurement procedures and company systems and contributes positively to procurement operations. Displays willingness to learn and adapt while maintaining acceptable accuracy in daily procurement activities', 'Arunima has shown noticeable improvement compared to the previous review period, particularly in procurement process understanding, system utilization, and professional conduct. Continued focus is required on quality of work, accuracy, initiative, and independent task management to further enhance performance and support departmental objectives.', 'The overall score of 62/100 reflects satisfactory performance and demonstrates positive improvement from the previous evaluation period. The employee has made progress in procurement knowledge, system usage, collaboration, and professional conduct. Continued development in work quality, initiative, problem-solving, and task ownership is recommended to achieve a higher level of performance and readiness for increased responsibilities.', NULL, NULL, NULL, '2026-09-20T14:43:24.848542+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('847fc837-19f8-49f2-9195-fabbe4a280af', '592be0f6-2da4-4555-a1cf-2b82ea2b13d4', '2026-09-02', '62', NULL, '["3","4","3","3","3","3","3","3","3","3","3","4","3","3","3","3","2","2","3","2","3","4","4","3","3","4","4","4","3","2"]'::jsonb, 'The primary development area is procurement governance and analytical capability. Greater attention is required in procurement record accuracy, audit readiness, spend analysis, reporting quality, and the use of procurement data to support business decisions. Compliance controls and documentation standards should be strengthened to minimise operational and audit risks', 'Focus on implementing stronger procurement controls, maintaining complete and accurate procurement records, improving supplier performance monitoring, and increasing the use of procurement analytics to identify cost-saving opportunities. Procurement reporting should become more data-driven, with measurable KPIs and regular management reviews.', 'Demonstrates solid leadership and workload management abilities, with strong responsiveness to internal stakeholders and effective supplier communication. Maintains acceptable procurement planning and inventory coordination practices and shows good proficiency in ERP and procurement systems', 'Rateb Alzeer demonstrates commitment to daily procurement operations and maintains constructive working relationships with internal stakeholders and suppliers. Leadership and coordination skills are evident; however, greater focus is needed on procurement controls, compliance documentation, reporting accuracy, and strategic cost management to improve departmental performance and support business objectives more effectively.', 'Recommendation: Retain with Performance Improvement Objectives for Q3. Rateb Alzeer shows capability in leadership, supplier coordination, and operational procurement activities; however, measurable improvement is required in audit readiness, procurement record management, spend analysis, and reporting effectiveness. A structured improvement plan with procurement KPIs and quarterly review targets is recommended.', NULL, NULL, NULL, '2026-09-20T14:43:28.943108+00:00');
insert into public.evaluations (id, employee_id, evaluation_date, score, previous_score, ratings, employee_area_of_development, employee_improvement, employee_strength, direct_manager_comments, evaluator_comment, employee_signature, manager_signature, evaluator_signature, created_at) values ('ba51cf06-b6fd-40b7-9f3b-7eda0b6de465', '74484f50-2e43-4d5f-beb6-3e29865b8c3b', '2026-09-03', '55', NULL, '["3","3","3","3","2","3","3","3","2","3","2","3","3","3","3","3","2","2","2","3","3","3","3","3","3","3"]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-20T14:43:25.764835+00:00');
